-- MIGRACAO SPRINT 4: executar uma unica vez no schema Oracle ja usado na Sprint 3.
-- O script original cria IDs como GENERATED BY DEFAULT AS IDENTITY, mas nao cria sequences nomeadas.
-- Esta migracao preserva as tabelas e cria sequences explicitas a partir de MAX(ID) + 1.
-- As colunas IDENTITY aceitam os IDs informados pelo JPA por serem BY DEFAULT.
-- Se as sequences ja existirem, nao execute novamente sem revisar o schema.

DECLARE
    v_inicio NUMBER;
BEGIN
    SELECT NVL(MAX(ID), 0) + 1 INTO v_inicio FROM TRECHO_RODOVIA;
    EXECUTE IMMEDIATE 'CREATE SEQUENCE SEQ_TRECHO_RODOVIA START WITH ' || v_inicio || ' INCREMENT BY 1 NOCACHE';

    SELECT NVL(MAX(ID), 0) + 1 INTO v_inicio FROM EQUIPE_MANUTENCAO;
    EXECUTE IMMEDIATE 'CREATE SEQUENCE SEQ_EQUIPE_MANUTENCAO START WITH ' || v_inicio || ' INCREMENT BY 1 NOCACHE';

    SELECT NVL(MAX(ID), 0) + 1 INTO v_inicio FROM INTERVENCAO_OPERACIONAL;
    EXECUTE IMMEDIATE 'CREATE SEQUENCE SEQ_INTERVENCAO_OPERACIONAL START WITH ' || v_inicio || ' INCREMENT BY 1 NOCACHE';

    SELECT NVL(MAX(ID), 0) + 1 INTO v_inicio FROM RELATORIO_PRIORIDADE;
    EXECUTE IMMEDIATE 'CREATE SEQUENCE SEQ_RELATORIO_PRIORIDADE START WITH ' || v_inicio || ' INCREMENT BY 1 NOCACHE';
END;
/
